detail.themeSheet:
@layer graview-theme {
.mast h2 { letter-spacing: 0.25em; padding: 40px; text-transform: uppercase; }
.lent { color: rgb(200, 30, 30); font-family: "Rock Face", serif; }
.baloo { font-family: "Baloo 2", monospace; }
}

detail.ownSheet:
@layer graview-view {
.mast { display: flex; align-items: center; gap: 12px; padding: 12px; }
.mast h2 { margin: 0; font-family: var(--graview-font-display); border-radius: var(--graview-radius); border: 1px solid var(--graview-edge); padding: 4px 8px; }
.mast .lent { color: rgb(1, 2, 3); font-family: monospace; }
.mast .own { font-family: "graview-view-1b0yszj Own Face", monospace; }
.mast .big { font-family: "Big Face", monospace; }
}

